import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 크기 기본값·최대값
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 200;
// 가정: 메시지 구분은 항상 CHAT
const MESSAGE_TYPE = 'CHAT';
// 가정: 첨부파일의 업무 대상 유형
const FILE_TARGET_TYPE = 'MESSENGER_MESSAGE';

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 숫자로 입력해 주세요.');
  }
  return text;
}

// 가정: 대화방 참여자 테이블이 없어, 방을 만든 사람과 그 방의 메시지 발신자·수신자를 참여자로 본다
async function roomMembers(db: Db, roomId: string): Promise<string[]> {
  const rows = await db.query(
    'SELECT DISTINCT t.member AS "employeeId" FROM ('
      + ' SELECT creator_id AS member FROM messenger_room WHERE messenger_room_id = CAST(:roomId AS bigint)'
      + ' UNION SELECT m.sender_id AS member FROM messenger_message m WHERE m.messenger_room_id = CAST(:roomId AS bigint)'
      + ' UNION SELECT r.recipient_id AS member FROM messenger_message_recipient r'
      + ' JOIN messenger_message m ON m.messenger_message_id = r.messenger_message_id'
      + ' WHERE m.messenger_room_id = CAST(:roomId AS bigint)'
      + ') t',
    { roomId },
  );
  return rows.map((row: any) => String(row.employeeId));
}

async function requireRoomMember(db: Db, roomId: string, userId: string): Promise<string[]> {
  const rooms = await db.query(
    'SELECT messenger_room_id AS "messengerRoomId" FROM messenger_room WHERE messenger_room_id = CAST(:roomId AS bigint)',
    { roomId },
  );
  if (rooms.length === 0) {
    throw new ApiError(404, 'MESSENGER_ROOM_NOT_FOUND', '대화방을 찾을 수 없습니다.');
  }
  const members = await roomMembers(db, roomId);
  if (!members.includes(userId)) {
    throw new ApiError(422, 'ROOM_ACCESS_DENIED', '대화방 참여자만 사용할 수 있습니다.');
  }
  return members;
}

async function insertMessage(
  db: Db,
  userId: string,
  roomId: string | null,
  content: string | null,
  replyTo: string | null,
  receivers: string[],
): Promise<{ messengerMessageId: number; sentAt: string }> {
  const rows = await db.query(
    'INSERT INTO messenger_message (messenger_room_id, sender_id, reply_to_message_id, message_type, content, sent_at, created_at, updated_at)'
      + ' VALUES (CAST(:roomId AS bigint), CAST(:userId AS bigint), CAST(:replyTo AS bigint), :messageType, :content, now(), now(), now())'
      + ' RETURNING messenger_message_id AS "messengerMessageId", sent_at AS "sentAt"',
    { roomId, userId, replyTo, messageType: MESSAGE_TYPE, content },
  );
  const created = rows[0];
  for (const receiver of receivers) {
    if (receiver === userId) {
      continue;
    }
    await db.execute(
      'INSERT INTO messenger_message_recipient (messenger_message_id, recipient_id, read_status, read_at, created_at, updated_at)'
        + ' VALUES (CAST(:messageId AS bigint), CAST(:receiver AS bigint), :readStatus, NULL, now(), now())'
        + ' ON CONFLICT (messenger_message_id, recipient_id) DO NOTHING',
      { messageId: String(created.messengerMessageId), receiver, readStatus: '안읽음' },
    );
  }
  return created;
}

@Controller('api/v1')
export class FnSfr03602Controller {
  @Post('/messenger-messages')
  @HttpCode(200)
  async createMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const roomId = idOf(data['messengerRoomId'], '대화방 ID');
    const content = data['content'];
    if (typeof content !== 'string' || content.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 내용을 입력해 주세요.');
    }
    const replyTo = data['replyToMessageId'] === undefined || data['replyToMessageId'] === null || data['replyToMessageId'] === ''
      ? null
      : idOf(data['replyToMessageId'], '답장 원본 메시지 ID');
    const filesRaw = data['files'];
    if (filesRaw !== undefined && filesRaw !== null && !Array.isArray(filesRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부 파일 목록 형식이 올바르지 않습니다.');
    }
    const files: Record<string, unknown>[] = [];
    for (const item of (filesRaw ?? []) as unknown[]) {
      if (item === null || typeof item !== 'object' || Array.isArray(item)) {
        throw new ApiError(422, 'FILE_UPLOAD_FAILED', '파일 정보가 올바르지 않아 전송하지 못했습니다.');
      }
      const file = item as Record<string, unknown>;
      const name = file['fileName'];
      if (typeof name !== 'string' || name.trim() === '' || name.length > 255) {
        throw new ApiError(422, 'FILE_UPLOAD_FAILED', '파일 이름이 비었거나 너무 길어 전송하지 못했습니다.');
      }
      const size = file['fileSize'];
      if (size !== undefined && size !== null && size !== '' && !/^[0-9]+$/.test(String(size))) {
        throw new ApiError(422, 'FILE_UPLOAD_FAILED', '파일 크기가 올바르지 않아 전송하지 못했습니다.');
      }
      files.push(file);
    }
    return transaction(async (db: Db) => {
      const members = await requireRoomMember(db, roomId, user.id);
      if (replyTo !== null) {
        const originals = await db.query(
          'SELECT messenger_message_id FROM messenger_message WHERE messenger_message_id = CAST(:replyTo AS bigint)',
          { replyTo },
        );
        if (originals.length === 0) {
          throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '답장할 원본 메시지를 찾을 수 없습니다.');
        }
      }
      // 그룹 대화방의 모든 참여자에게 수신자 행을 만든다 (오프라인 수신자는 서버에 보관되어 접속 시 읽는다)
      const created = await insertMessage(db, user.id, roomId, content, replyTo, members);
      for (const file of files) {
        const fileName = String(file['fileName']);
        const dot = fileName.lastIndexOf('.');
        const extension = dot >= 0 ? fileName.substring(dot + 1).substring(0, 20) : null;
        const size = file['fileSize'] === undefined || file['fileSize'] === null || file['fileSize'] === '' ? null : String(file['fileSize']);
        await db.execute(
          'INSERT INTO attachment (uploader_id, file_name, file_extension, file_size, ecm_ref, file_hash, target_type, target_id, created_at, updated_at)'
            + ' VALUES (CAST(:userId AS bigint), :fileName, :extension, CAST(:size AS bigint), :ecmRef, :fileHash, :targetType, CAST(:targetId AS bigint), now(), now())',
          {
            userId: user.id,
            fileName,
            extension,
            size,
            ecmRef: typeof file['ecmRef'] === 'string' ? file['ecmRef'] : null,
            fileHash: typeof file['fileHash'] === 'string' ? file['fileHash'] : null,
            targetType: FILE_TARGET_TYPE,
            targetId: String(created.messengerMessageId),
          },
        );
      }
      return { messengerMessageId: created.messengerMessageId, sentAt: created.sentAt };
    });
  }

  @Post('/messenger-messages/:messengerMessageId/forward')
  @HttpCode(200)
  async forwardMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const messageId = idOf(req.params['messengerMessageId'], '메시지 ID');
    const hasRoom = data['targetRoomId'] !== undefined && data['targetRoomId'] !== null && data['targetRoomId'] !== '';
    const targetRoomId = hasRoom ? idOf(data['targetRoomId'], '전달받을 대화방 ID') : null;
    const employeesRaw = data['targetEmployeeIds'];
    if (employeesRaw !== undefined && employeesRaw !== null && !Array.isArray(employeesRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '전달받을 사용자 목록 형식이 올바르지 않습니다.');
    }
    const targetEmployees: string[] = [];
    for (const value of (employeesRaw ?? []) as unknown[]) {
      const id = idOf(value, '전달받을 사용자 ID');
      if (!targetEmployees.includes(id)) {
        targetEmployees.push(id);
      }
    }
    return transaction(async (db: Db) => {
      const originals = await db.query(
        'SELECT content AS "content" FROM messenger_message WHERE messenger_message_id = CAST(:messageId AS bigint)',
        { messageId },
      );
      if (originals.length === 0) {
        throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '전달할 메시지를 찾을 수 없습니다.');
      }
      if (targetRoomId === null && targetEmployees.length === 0) {
        throw new ApiError(422, 'FORWARD_TARGET_REQUIRED', '전달할 대화방 또는 사용자를 지정해 주세요.');
      }
      const content: string | null = originals[0].content;
      const createdIds: number[] = [];
      const copyFiles = async (newId: number) => {
        await db.execute(
          'INSERT INTO attachment (uploader_id, file_name, file_extension, file_size, ecm_ref, file_hash, target_type, target_id, created_at, updated_at)'
            + ' SELECT CAST(:userId AS bigint), file_name, file_extension, file_size, ecm_ref, file_hash, target_type, CAST(:newId AS bigint), now(), now()'
            + ' FROM attachment WHERE target_type = :targetType AND target_id = CAST(:messageId AS bigint)',
          { userId: user.id, newId: String(newId), targetType: FILE_TARGET_TYPE, messageId },
        );
      };
      if (targetRoomId !== null) {
        const members = await requireRoomMember(db, targetRoomId, user.id);
        const created = await insertMessage(db, user.id, targetRoomId, content, null, members);
        await copyFiles(created.messengerMessageId);
        createdIds.push(created.messengerMessageId);
      }
      if (targetEmployees.length > 0) {
        for (const employeeId of targetEmployees) {
          const found = await db.query(
            'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
            { employeeId },
          );
          if (found.length === 0) {
            throw new ApiError(400, 'VALIDATION_FAILED', '전달받을 사용자를 찾을 수 없습니다.');
          }
        }
        const created = await insertMessage(db, user.id, null, content, null, targetEmployees);
        await copyFiles(created.messengerMessageId);
        createdIds.push(created.messengerMessageId);
      }
      return { messengerMessageId: createdIds[0] };
    });
  }

  @Get('/messenger-message-recipients')
  async listMessengerMessageRecipients(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const messageId = idOf(query['messengerMessageId'], '메시지 ID');
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? String(DEFAULT_PAGE_SIZE) : String(query['size']);
    if (!/^[0-9]+$/.test(pageText) || !/^[0-9]+$/.test(sizeText) || Number(sizeText) < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 쪽 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Number(sizeText), MAX_PAGE_SIZE);
    return transaction(async (db: Db) => {
      const items = await db.query(
        'SELECT recipient_id AS "recipientId", read_status AS "readStatus", read_at AS "readAt"'
          + ' FROM messenger_message_recipient WHERE messenger_message_id = CAST(:messageId AS bigint)'
          + ' ORDER BY messenger_message_recipient_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { messageId, size: String(size), offset: String(page * size) },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM messenger_message_recipient WHERE messenger_message_id = CAST(:messageId AS bigint)',
        { messageId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/messenger-messages/:messengerMessageId/read')
  @HttpCode(200)
  async readMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = idOf(req.params['messengerMessageId'], '메시지 ID');
    return transaction(async (db: Db) => {
      const rows = await db.query(
        'SELECT messenger_message_recipient_id AS "id" FROM messenger_message_recipient'
          + ' WHERE messenger_message_id = CAST(:messageId AS bigint) AND recipient_id = CAST(:userId AS bigint)',
        { messageId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '수신 대상 메시지를 찾을 수 없습니다.');
      }
      const updated = await db.query(
        'UPDATE messenger_message_recipient SET read_status = :readStatus, read_at = COALESCE(read_at, now()), updated_at = now()'
          + ' WHERE messenger_message_id = CAST(:messageId AS bigint) AND recipient_id = CAST(:userId AS bigint)'
          + ' RETURNING read_status AS "readStatus"',
        { readStatus: '읽음', messageId, userId: user.id },
      );
      return { readStatus: updated[0].readStatus };
    });
  }
}

